For a non-empty collection of bases $\mathscr{B}' \subseteq \mathbb N \setminus \{1\}$, let $\mathscr{C}$ be as in (4.1) and let $\mathcal S = \{\mathtt s_m : m \geq 1\} \subseteq \mathbb N \setminus \{1,2\}$ be an ordered sequence of (not necessarily distinct) bases obeying (4.2). Then there is a sequence $\{\kappa_m=\kappa(\mathtt s_m):\ m\geq 1\} \subseteq (0,1)$ as follows.   
\vskip0.1in 
\noindent Suppose that $\mu = \mu(\pmb{\Pi})$ is the skewed measure whose parameter $\pmb{\Pi} = (\mathcal S, \mathcal A, \mathcal B, \mathcal D, \mathcal E)$ satisfies the assumptions: $\mathcal A, \mathcal B$ obey (4.17) and (4.18) with the above-mentioned choice of $\{\kappa_m\}$, 
\begin{equation*} 
\mathcal E = \{\varepsilon_m \} \subseteq (0, 1), \quad  0 \in \mathscr{D}_m \subsetneq \mathbb Z_{\mathtt s_m} \; \; \text{ for all } m \geq 1.
\end{equation*} 
Then $\mu$-almost every point $x$ is $b$-normal for every $b \in \mathscr{B}_1$, where 
\begin{equation} 
\mathscr{B}_1 := \bigl\{b \in \mathbb N \setminus \{1,2\} : \text{ for every } \mathtt s \in \mathscr{C}, \exists \,\text{ a prime } \, \mathtt p \ni \;  \mathtt p \nmid b \; \text{ but } \; \mathtt p \mid \mathtt s \bigr\}.
\end{equation}

Given any non-empty collection of bases $\mathscr{B}' \subseteq \mathbb N \setminus \{1\}$ and one of its minimal representations $\mathscr{C}$ obeying (4.1), let $\mathcal S = \{\mathtt s_m : m \geq 1\} \subseteq \mathbb N \setminus \{1,2\}$ be an ordered sequence of (not necessarily distinct) bases obeying (4.2).
Then there exists a numerical sequence $\{\kappa_m = \kappa (\mathtt s_m): m \geq 1\} \subseteq (0,1)$ as follows.  
\vskip0.1in 
\noindent Suppose that $\mu = \mu(\pmb{\Pi})$ is the skewed measure associated with $\pmb{\Pi} = (\mathcal S, \mathcal A, \mathcal B, \mathcal D, \mathcal E)$, where $\mathcal A, \mathcal B$ obey (4.17) and (4.18) with this choice of $\{\kappa_m\}$, $\mathcal E = \{\varepsilon_m \} \subseteq (0, 1)$, and  

\begin{equation}  
\{0, 1\} \subseteq \mathscr{D}_m \subsetneq \mathbb Z_{\mathtt s_m} \quad \text{ for all } m \geq 1.
\end{equation}
Then  $\mu$-almost every point $x$ is $b$-normal for every
\begin{equation} 
b \in \mathscr{B} := \{2, 3, \ldots\} \setminus \overline{\mathscr B'}.
\end{equation}

Let $\pmb{\Pi}$ be any choice of parameters as in (3.1), and let $\varphi_m$ be the $m^{\text{th}}$ density function (3.12) that occurs in the construction of $\mu = \mu(\pmb{\Pi})$.  Then for every $h \in \mathbb Z \setminus \{0\}$ and $\mathscr{S}_m$ as in (12.7), the summability condition (12.6) holds 
\begin{enumerate}[(a)]
\item for every $b \in \mathscr{B}_1$, provided $\pmb{\Pi}$ obeys the hypotheses of Proposition 11.3;   
\item for every $b \in \mathscr{B}$, provided $\pmb{\Pi}$ obeys the hypotheses of Proposition 4.5. 
\end{enumerate}

Let $\pmb{\Pi}$ be a choice of parameters obeying (3.1), (3.2) and (3.3). Then for every $h \in \mathbb Z \setminus \{0\}$ and $b \in \mathbb N \setminus \{1\}$, there is a constant $C(h, b, \pmb{\Pi}) > 0$ such that for all $m \geq 1$, 
\begin{equation}  
\mathcal U_m(h, b) := \sum_{N=1}^{\infty} N^{-3} \mathscr{U}_m(N; h, b)   \leq C(h, b, \pmb{\Pi})  {\mathtt s_{m-1}^{\mathtt b_{m-1}}}{\mathtt s_m^{-\frac{\mathtt a_m}{2}}}.
\end{equation}

Suppose that one of the following assumptions holds:
\begin{enumerate}[(a)] 
\item The parameter $\pmb{\Pi}$ obeys the hypotheses of Proposition 11.3, and $b \in \mathscr{B}_1$ as in (11.12). 
\item  The parameter $\pmb{\Pi}$ obeys the hypotheses of Proposition 4.5, and $b \in \mathscr{B}$ as in (4.20). 
\end{enumerate} 

Then there is a sequence of positive real numbers $\{\mathtt c_m(h, b, \pmb{\Pi}) : m \geq 1\}$ such that  
\begin{equation}  
\mathcal V_m(h,b) := \sum_{N=1}^{\infty} N^{-3} \mathscr{V}_m(N; h, b)  \leq \mathtt c_m(h, b, \pmb{\Pi}), \quad \sum_{m=1}^{\infty} \mathtt c_m(h, b, \pmb{\Pi}) < \infty. 
\end{equation}

Let $\pmb{\Pi}$ be any choice of parameters obeying (3.1), (3.2) and (3.3). Then for any $h \in \mathbb Z \setminus \{0\}$, $b \in \mathbb N \setminus \{1\}$, there exists a sequence $\{\mathtt c_m(h, b) : m \geq 1\} \subseteq (0, \infty)$ such that   
 \begin{equation} 
 \mathcal V_{m1} \leq \sum_{j=1}^{4} \mathcal W_j \leq \mathtt c_m(h, b) \; \; \text{ for all } m \geq 1, \quad\text{with}\; \;  \sum_{m=1}^{\infty} \mathtt c_m(h, b) < \infty. 
 \end{equation}
